#!/usr/bin/env node
'use strict';
/**
 * CG-001 — build-dock.js
 * Emits the two browser bundles from dock.json + the CG-000 snapshots.
 *
 * Both outputs are GENERATED — never hand-edited. Each carries
 *   GENERATED BY CG/build-dock.js — DO NOT HAND-EDIT
 * as its first line.
 *
 * Offline, deterministic, zero dependencies. NO WALL-CLOCK anywhere in the output:
 * every timestamp comes from the inputs' own `_probe.fetchedAt` or the source mtime,
 * which is what makes the page diffable and the tests real (oracle P11).
 *
 * The bundles are plain classic scripts (no module system) so they load from file://,
 * where fetch() and <script type="module"> are blocked. The page reads
 * window.CG_DOCK / window.CG_RELICS synchronously at parse time.
 *
 *   node CG/build-dock.js
 */

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const DOCK_JSON = path.join(ROOT, 'derived', 'dock.json');
const PRICES_IN = path.join(ROOT, 'baked', 'probes', 'market__wfinfo-prices.json');
const FILTERED_IN = path.join(ROOT, 'baked', 'probes', 'market__wfinfo-filtered_items.json');
const OUT_DOCK = path.join(ROOT, 'dock.data.js');
const OUT_RELICS = path.join(ROOT, 'relics.data.js');

const BANNER = 'GENERATED BY CG/build-dock.js — DO NOT HAND-EDIT';

/** Snapshot age in whole hours, derived from the snapshot's own clock (no wall clock). */
function ageLabel(fetchedAt) {
  const t = Date.parse(fetchedAt);
  if (Number.isNaN(t)) return 'UNKNOWN AGE';
  // Age is measured against the NEWEST input timestamp so the bundle stays deterministic.
  return 'SNAPSHOT ' + String(fetchedAt).replace('T', ' ').replace(/\..*$/, '').replace('Z', 'Z') +
    ' · static snapshot, not live';
}

function main() {
  for (const f of [DOCK_JSON, PRICES_IN, FILTERED_IN]) {
    if (!fs.existsSync(f)) {
      console.error('build-dock FAILED: required input missing — ' + f);
      console.error('Run: node CG/import-xlsx.js');
      process.exit(1);
    }
  }

  const dock = JSON.parse(fs.readFileSync(DOCK_JSON, 'utf8'));
  const pricesJson = JSON.parse(fs.readFileSync(PRICES_IN, 'utf8'));
  const filteredJson = JSON.parse(fs.readFileSync(FILTERED_IN, 'utf8'));

  const priceRows = pricesJson.data || [];
  const filtered = filteredJson.data || {};

  const snapshot = {
    _doc: 'The snapshot this bundle was built from. CG-001 has NO live reader.',
    pricesFetchedAt: pricesJson._probe ? pricesJson._probe.fetchedAt : null,
    filteredFetchedAt: filteredJson._probe ? filteredJson._probe.fetchedAt : null,
    age: ageLabel(pricesJson._probe ? pricesJson._probe.fetchedAt : null),
    liveReader: false,
  };

  // --- dock.data.js: the whole canonical master + prices + catalog + errors ---
  const dockPayload = Object.assign({}, dock, {
    prices: priceRows,
    eqmt: filtered.eqmt || {},
    errors: filtered.errors || [],
    ignoredItems: filtered.ignored_items || {},
    snapshot,
  });
  const dockOut =
    '/* ' + BANNER + ' */\n' +
    '/* Classic script include for file://. No module system, no fetch. */\n' +
    'window.CG_DOCK = ' + JSON.stringify(dockPayload, null, 1) + ';\n';

  // --- relics.data.js: reward tables, loaded only when the relic panel opens ---
  const relicPayload = {
    _doc: 'Relic reward tables from the CG-000 snapshot. Loaded on demand by the relic panel.',
    tiers: Object.keys(filtered.relics || {}),
    relics: filtered.relics || {},
    errors: filtered.errors || [],
    snapshot,
  };
  const relicsOut =
    '/* ' + BANNER + ' */\n' +
    '/* Classic script include for file://. No module system, no fetch. */\n' +
    'window.CG_RELICS = ' + JSON.stringify(relicPayload, null, 1) + ';\n';

  fs.writeFileSync(OUT_DOCK, dockOut, 'utf8');
  fs.writeFileSync(OUT_RELICS, relicsOut, 'utf8');

  console.log('wrote ' + OUT_DOCK);
  console.log('wrote ' + OUT_RELICS);
  const jc = dock.joinCoverage;
  console.log('joinCoverage: ' + jc.joined + '/' + jc.priceRows +
    '  unjoined=' + jc.unjoinedCount + '  ' + JSON.stringify(jc.unjoinedByClass));
  console.log('catalogMiss: ' + JSON.stringify(dock.catalogMiss.items));
  console.log('segments: ' + dock.segmentCoverage.pricedSegments + '/' + dock.segmentCoverage.totalSegments +
    ' (' + dock.segmentCoverage.pct + '%)');
  console.log('priceable: ' + dock.priceability.priceable + '/' + dock.items.length);
  console.log('errors surfaced in the relic panel: ' + dock.feedErrors.count);
}

if (require.main === module) {
  try {
    main();
  } catch (err) {
    console.error('build-dock FAILED: ' + err.message);
    process.exit(1);
  }
}